class MockGCodeView:
    def __init__(self, text):
        lines = text.split('\n')
        self.headLines = lines[:100]  # First 100 lines as header
        self.text = text
        self.containerType = 'gcode'
        self.plateNumber = 1

    def iterLines(self):
        return self.text.split('\n')


def test_klipper_detection():
    """Test that Klipper G-code from OrcaSlicer is correctly detected."""
    gview = MockGCodeView(KLIPPER_SAMPLE)
    guess = detectSlicer(gview)

    print("=== Klipper/Snapmaker Detection Test ===")
    print(f"Detected: {guess.name}")
    print(f"Confidence: {guess.confidence}")
    print(f"Hints: {guess.hints}")

    assert guess.name == 'orca', f"Expected 'orca', got '{guess.name}'"
    assert guess.confidence == 1.0, f"Expected confidence 1.0, got {guess.confidence}"
    print("✓ Detection test passed\n")

    return guess


def test_klipper_extraction():
    """Test that values are correctly extracted from Klipper/Snapmaker G-code."""
    gview = MockGCodeView(KLIPPER_SAMPLE)
    guess = detectSlicer(gview)
    parsed = extractParsedValues(gview, guess)

    print("=== Klipper/Snapmaker Extraction Test ===")
    print(f"Slicer: {parsed.meta.get('slicer')}")
    print(f"Is Klipper: {parsed.meta.get('isKlipper')}")
    print(f"Print time (sec): {parsed.fieldValues.get('printTimeSec')}")
    print(f"Total layers: {parsed.fieldValues.get('totalLayers')}")
    print(f"Max Z height: {parsed.fieldValues.get('maxZHeight')}")
    print(f"Filament used (g): {parsed.fieldValues.get('filamentUsedGrams')}")
    print(f"Filament weights: {parsed.fieldValues.get('filamentWeights')}")
    print(f"Filament cost: {parsed.fieldValues.get('filamentCost')}")
    print(f"G-code flavor: {parsed.fieldValues.get('gcode_flavor')}")
    print(f"Printer model: {parsed.fieldValues.get('printer_model')}")
    print(f"Extruder count: {parsed.fieldValues.get('extruderCount')}")
    print(f"Extruder colors: {parsed.fieldValues.get('extruderColors')}")
    print(f"Tools used: {parsed.fieldValues.get('toolsUsed')}")
    print(f"Bed temperature: {parsed.fieldValues.get('buildPlateTemperature')}")
    print(f"Nozzle temperature: {parsed.fieldValues.get('hotendTemperature')}")
    print(f"Thumbnails: {len(parsed.fieldValues.get('thumbnails', []))} found")

    # Verify critical fields
    assert parsed.meta.get('slicer') == 'orca', "Wrong slicer in meta"
    assert parsed.meta.get('isKlipper') == True, "Should detect Klipper"

    # Print time: 43m 45s = 43*60 + 45 = 2625 seconds
    assert parsed.fieldValues.get('printTimeSec') == '2625', f"Wrong print time: {parsed.fieldValues.get('printTimeSec')}"

    # Total layers (should use 'total layers count' fallback)
    assert parsed.fieldValues.get('totalLayers') in ('126', '127'), f"Wrong layer count: {parsed.fieldValues.get('totalLayers')}"

    # Max Z height
    assert parsed.fieldValues.get('maxZHeight') == '25.45', f"Wrong Z height: {parsed.fieldValues.get('maxZHeight')}"

    # Filament weight
    assert parsed.fieldValues.get('filamentUsedGrams') == '21.81', f"Wrong filament weight: {parsed.fieldValues.get('filamentUsedGrams')}"

    # Filament cost
    assert parsed.fieldValues.get('filamentCost') == '0.50', f"Wrong filament cost: {parsed.fieldValues.get('filamentCost')}"

    # G-code flavor should be klipper
    assert parsed.fieldValues.get('gcode_flavor') == 'klipper', f"Wrong gcode_flavor: {parsed.fieldValues.get('gcode_flavor')}"

    # Printer model
    assert parsed.fieldValues.get('printer_model') == 'Snapmaker U1', f"Wrong printer model: {parsed.fieldValues.get('printer_model')}"

    # Extruder count (4 extruders for toolchanger)
    assert parsed.fieldValues.get('extruderCount') == '4', f"Wrong extruder count: {parsed.fieldValues.get('extruderCount')}"

    # Thumbnails should be extracted
    thumbnails = parsed.fieldValues.get('thumbnails', [])
    assert len(thumbnails) >= 1, f"Expected at least 1 thumbnail, got {len(thumbnails)}"

    # Check thumbnail dimensions
    thumb48 = next((t for t in thumbnails if t.get('width') == 48), None)
    assert thumb48 is not None, "Expected 48x48 thumbnail"
    assert thumb48.get('height') == 48, "Wrong thumbnail height"
    assert thumb48.get('format') == 'png', "Expected PNG format"

    print("✓ Extraction test passed\n")

    return parsed


def test_thumbnail_extraction():
    """Test that thumbnails are correctly extracted from G-code."""
    gview = MockGCodeView(KLIPPER_SAMPLE)
    guess = detectSlicer(gview)
    parsed = extractParsedValues(gview, guess)

    print("=== Thumbnail Extraction Test ===")
    thumbnails = parsed.fieldValues.get('thumbnails', [])
    print(f"Found {len(thumbnails)} thumbnail(s)")

    for i, thumb in enumerate(thumbnails):
        print(f"  Thumbnail {i + 1}:")
        print(f"    Size: {thumb.get('width')}x{thumb.get('height')}")
        print(f"    Format: {thumb.get('format')}")
        print(f"    Data length: {len(thumb.get('data', ''))} chars")
        if thumb.get('valid') == False:
            print(f"    Valid: False (decode failed)")

    # Verify plateImageBase64 is set
    plateImage = parsed.fieldValues.get('plateImageBase64')
    assert plateImage is not None, "plateImageBase64 should be set"
    print(f"  plateImageBase64 set: Yes ({len(plateImage)} chars)")

    print("✓ Thumbnail test passed\n")


