    try:
        test_klipper_detection()
        test_klipper_extraction()
        test_thumbnail_extraction()
        print("=" * 50)
        print("✓ ALL TESTS PASSED!")
        print("=" * 50)
    except AssertionError as e:
        print(f"\n✗ TEST FAILED: {e}")
        exit(1)
    except Exception as e:
        print(f"\n✗ ERROR: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
